def svg(p):
    return f'''<svg viewBox="0 0 620 460" role="img" aria-label="Abstract visualization for {esc(p['short'])}"><g class="spin" fill="none" stroke="var(--accent)" opacity=".55"><circle cx="310" cy="230" r="178" stroke-width="1"/><circle cx="310" cy="230" r="126" stroke-width="1" stroke-dasharray="4 12"/><ellipse cx="310" cy="230" rx="220" ry="72" transform="rotate(28 310 230)"/><ellipse cx="310" cy="230" rx="220" ry="72" transform="rotate(-28 310 230)"/></g><g class="pulse" fill="none" stroke="var(--accent2)" stroke-width="2"><path d="M100 280 C175 90 245 370 320 185 S470 140 535 265"/><path d="M80 215 C180 360 230 90 335 255 S470 330 560 165" opacity=".45"/></g><g fill="var(--accent2)"><circle cx="310" cy="230" r="22"/><circle cx="125" cy="274" r="6"/><circle cx="485" cy="172" r="8"/><circle cx="388" cy="326" r="5"/><circle cx="245" cy="116" r="5"/></g><text x="310" y="236" text-anchor="middle" fill="var(--bg)" font-size="11" font-family="Arial" font-weight="700" letter-spacing="2">{esc(p['short']).upper()[:18]}</text></svg>'''

def page(p):
    accent = PALETTES[p['theme']]
    visual = THEMES[p['theme']]
    steps=''.join(f'<div class="step reveal"><b>{i+1:02d}</b><strong>{esc(s.split("—")[0])}</strong><span>{esc(s.split("—",1)[1] if "—" in s else "")}</span></div>' for i,s in enumerate(p['method']))
    cards=''.join(f'<div class="card reveal"><h3>{esc(c)}</h3><p>Source-grounded concept in the proposed system.</p></div>' for c in p['concepts'])
    tags=''.join(f'<span class="tag">{esc(x)}</span>' for x in p['keywords'])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Research exhibition page for {esc(p['title'])}"><title>{esc(p['short'])} · Research Exhibition</title><style>{CSS}</style><style>:root{{--accent:{accent};--accent2:#fff3c4}}</style><style>{visual}</style></head><body class="{p['theme']}"><nav class="topbar"><span class="brand">Research / Exhibition 01—15</span><a href="index.html">All papers ↗</a></nav><header class="hero"><div class="hero-grid"><div><div class="eyebrow">{esc(p['kicker'])}</div><h1>{esc(p['title'])}</h1><p class="subtitle">{esc(p['subtitle'])}</p><div class="meta"><strong>{esc(p['authors'])}</strong>{esc(p['affil'])}<br>{esc(p['venue'])}</div><a class="scroll" href="#context">Scroll to enter ↓</a></div><div class="orbit">{svg(p)}</div></div></header><main><section id="context" class="section"><div class="section-head"><span class="label">01 / Research signal</span><h2>The question beneath the system</h2></div><div class="two"><p class="lede">{esc(p['question'])}</p><div class="note"><strong>Abstract, condensed from the supplied source</strong><p>{esc(p['abstract'])}</p></div></div></section><section class="section dark"><div class="section-head"><span class="label">02 / Context</span><h2>Why this work exists</h2></div><div class="two"><div><p class="lede">{esc(p['problem'])}</p></div><div class="note"><p><span class="badge">Evidence boundary</span></p><p>Every statement on this page is based on the supplied PDF. Interpretive language is used for the exhibition design; publication details and results are not filled in where the source is silent.</p></div></div></section><section class="section"><div class="section-head"><span class="label">03 / Core concepts</span><h2>A system with a point of view</h2></div><div class="cards">{cards}</div></section><section class="section" style="background:#e9e4da;max-width:none"><div class="section-head"><span class="label">04 / Method map</span><h2>From input to accountable output</h2></div><div class="flow">{steps}</div></section><section class="section dark"><div class="section-head"><span class="label">05 / Evidence</span><h2>What the paper actually reports</h2></div><div class="evidence"><div><p class="quote">{esc(p['finding'])}</p></div><div class="facts"><div class="fact"><small>Available evidence</small><p>{esc(p['evidence'])}</p></div><div class="fact"><small>Publication status</small><p>{esc(p['availability'])}</p></div><div class="fact"><small>Keywords</small><div class="tags">{tags}</div></div></div></div></section><section class="section"><div class="section-head"><span class="label">06 / Citation card</span><h2>Keep the provenance visible</h2></div><div class="facts"><div class="fact"><small>Title</small><p>{esc(p['title'])}</p></div><div class="fact"><small>Authors</small><p>{esc(p['authors'])}</p></div><div class="fact"><small>Affiliation</small><p>{esc(p['affil'])}</p></div><div class="fact"><small>Venue / year</small><p>{esc(p['venue'])}</p></div></div></section><section class="closing"><div class="label" style="color:#fff">Closing takeaway</div><h2>Design the evidence chain, not just the interface.</h2><p>{esc(p['metaphor'])}</p><p><a href="index.html">← Return to the research collection</a></p></section></main><footer class="footer"><span>Source-led digital research exhibition</span><a href="index.html">Portfolio index</a></footer><script>const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('visible')),{{threshold:.12}});document.querySelectorAll('.reveal').forEach(e=>io.observe(e));</script></body></html>'''

def index():
    card_colors = PALETTES
    cards=''.join(f'''<a class="collection-card reveal" href="{p['slug']}.html" style="--card-accent:{card_colors[p['theme']]}" ><span class="card-no">{papers.index(p)+1:02d}</span><span class="card-kicker">{esc(p['kicker'])}</span><h2>{esc(p['short'])}</h2><p>{esc(p['metaphor'])}</p><span class="open">Open paper ↗</span></a>''' for p in papers)
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A curated digital exhibition of 15 research papers."><title>Research / Exhibition</title><style>{CSS}</style><style>.portfolio-hero{min-height:78vh;display:grid;align-items:end;padding:120px 7vw 80px;color:#fff;background:radial-gradient(circle at 80% 20%,#f17845 0,transparent 27%),linear-gradient(135deg,#0b0d12,#1c2532)}.portfolio-hero h1{font-family:var(--display);font-size:clamp(5rem,15vw,15rem);line-height:.78;letter-spacing:-.08em;text-transform:uppercase;margin:20px 0;max-width:1100px}.portfolio-hero p{max-width:600px;font-size:1.2rem;color:#d5d8dd}.collection{padding:110px 7vw;background:#f4f1eb}.collection-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:45px}.collection-head h2{font-family:var(--display);font-size:clamp(3rem,7vw,7rem);line-height:.85;text-transform:uppercase;letter-spacing:-.06em;margin:0}.collection-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;max-width:1400px;margin:auto}.collection-card{position:relative;display:flex;flex-direction:column;min-height:330px;padding:27px;background:var(--card);border:1px solid #d9d5cc;color:#17191d;text-decoration:none;overflow:hidden;transition:transform .35s,box-shadow .35s}.collection-card:before{content:"";position:absolute;left:0;top:0;width:100%;height:5px;background:var(--card-accent)}.collection-card:hover{transform:translateY(-7px);box-shadow:0 20px 40px #15182118}.card-no{font-family:var(--display);font-size:3rem;color:var(--card-accent);line-height:1}.card-kicker{font-size:.65rem;letter-spacing:.14em;font-weight:800;margin:20px 0 12px}.collection-card h2{font-family:var(--display);font-size:2.15rem;line-height:.9;text-transform:uppercase;letter-spacing:-.04em;margin:0;max-width:280px}.collection-card p{color:#72757d;font-size:.92rem;max-width:300px}.open{margin-top:auto;font-size:.75rem;text-transform:uppercase;letter-spacing:.12em;font-weight:700}.manifesto{padding:120px 7vw;background:#0b0d12;color:#fff}.manifesto-inner{max-width:1000px}.manifesto h2{font-family:var(--display);font-size:clamp(3rem,7vw,7rem);line-height:.85;letter-spacing:-.06em;text-transform:uppercase;margin:0 0 32px}.manifesto p{font-size:1.2rem;color:#c1c5cd;max-width:700px}@media(max-width:900px){.collection-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.collection-grid{grid-template-columns:1fr}.collection-head{display:block}.collection-head .label{display:block;margin-bottom:18px}}</style></head><body><nav class="topbar"><span class="brand">Research / Exhibition</span><span>15 papers · source-led</span></nav><header class="portfolio-hero"><div><div class="eyebrow">A digital research exhibition · 2026</div><h1>Signals<br>in the<br>system.</h1><p>Fifteen papers on agentic AI, sensing, safety, health, learning, and the infrastructures that make intelligence accountable.</p></div></header><section class="manifesto"><div class="manifesto-inner"><div class="label" style="color:#f17845">The collection</div><h2>Read the architecture behind the claim.</h2><p>Each paper has its own visual language. Every page separates source-stated evidence from exhibition interpretation and marks unavailable publication details instead of inventing them.</p></div></section><section class="collection"><div class="collection-head"><span class="label">01—15 / Browse the papers</span><h2>The archive</h2></div><div class="collection-grid">{cards}</div></section><footer class="footer"><span>Prepared from the supplied published research papers PDF</span><span>Open any card to enter a standalone page</span></footer><script>const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('visible')),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>io.observe(e));</script></body></html>'''.replace('{CSS}', CSS).replace('{cards}', cards)

def inventory():
    lines=['# Paper inventory','', 'Working inventory created from the supplied PDF: `published research papers.pdf`.','', '**Evidence rule:** publication metadata, methods, and findings below are transcribed or condensed from the source. “Unavailable” means the supplied material does not state the field. Numerical claims are retained only where the paper presents them; labels on the website identify illustrative, simulated, case-study, or source-reported status where relevant.','',f'**Distinct papers found:** {len(papers)}','']
    for i,p in enumerate(papers,1):
        lines += [f'## {i}. {p["title"]}',f'- **Authors:** {p["authors"]}',f'- **Affiliation:** {p["affil"]}',f'- **Venue / year:** {p["venue"]}',f'- **Abstract / scope:** {p["abstract"]}',f'- **Research problem:** {p["problem"]}',f'- **Method / proposed approach:** {"; ".join(p["method"])}',f'- **Evidence / findings:** {p["finding"]}',f'- **Keywords:** {", ".join(p["keywords"])}',f'- **DOI / URL availability:** {p["availability"]}', '']
    return '\n'.join(lines)

def readme():
    return '''# Signals in the System — Research Exhibition\n\nThis folder contains a self-contained digital exhibition built from the supplied `published research papers.pdf`.\n\n## View it\n\nOpen `index.html` in a modern browser. It links to 15 independent HTML pages; each page contains its own CSS, JavaScript, and inline SVG, so the collection can be copied or presented without a build step or external assets.\n\nFor a local presentation server, run `python -m http.server 8000` from this folder and open `http://localhost:8000`.\n\n## Contents\n\n- `index.html` — central portfolio and paper directory.\n- One `<slug>.html` file per distinct paper.\n- `paper-inventory.md` — source-grounded working inventory.\n- `published research papers.pdf` — supplied source retained in its original attachment location; the generated pages do not embed it.\n\n## Evidence and interpretation\n\nThe exhibition distinguishes source-stated material from design interpretation. Missing DOI, URL, author, affiliation, or results fields are labeled unavailable. Where a paper itself labels results as illustrative, simulated, planned, or case-study-only, the page preserves that boundary.\n'''

if __name__ == '__main__':
    for p in papers:
        (ROOT / f"{p['slug']}.html").write_text(page(p), encoding='utf-8')
    (ROOT/'index.html').write_text(index(), encoding='utf-8')
    (ROOT/'paper-inventory.md').write_text(inventory(), encoding='utf-8')
    (ROOT/'README.md').write_text(readme(), encoding='utf-8')
    print(f'Built {len(papers)} paper pages plus index, inventory, and README.')
